Here is the commit message:
block: fix qemu-img --help invocation

This fixes a bug introduced in commit ac1307ab, that caused the
'--help' option to not be recognized as a valid command, and not
print any help.

Signed-off-by: Jeff Cody <jcody@redhat.com>
Reviewed-by: Eric Blake <eblake@redhat.com>
Signed-off-by: Kevin Wolf <kwolf@redhat.com>

Here is the root cause:
The bug was caused by the absence of proper command-line option parsing for the `--help` flag in the `qemu-img.c` file, which led to the program not recognizing the option as valid and failing to display help information. This issue was introduced in a previous commit, indicating that the logic for handling command-line arguments was either removed or not implemented correctly.

Here is the patch:

 int main(int argc, char **argv)
 {
     const img_cmd_t *cmd;
     const char *cmdname;
+    int c;
+    int option_index = 0;
+    static const struct option long_options[] = {
+        {"help", no_argument, 0, 'h'},
+        {0, 0, 0, 0}
+    };

 #ifdef CONFIG_POSIX
     signal(SIGPIPE, SIG_IGN);
 #endif

     error_set_progname(argv[0]);
     qemu_init_exec_dir(argv[0]);

     qemu_init_main_loop();
     bdrv_init();
     if (argc < 2) {
         error_exit("Not enough arguments");
     }
     cmdname = argv[1];
-    argc--; argv++;

     /* find the command */
     for(cmd = img_cmds; cmd->name != NULL; cmd++) {
         if (!strcmp(cmdname, cmd->name)) {
-            return cmd->handler(argc, argv);
+            return cmd->handler(argc - 1, argv + 1);
         }
     }

+    c = getopt_long(argc, argv, "h", long_options, &option_index);
+
+    if (c == 'h') {
+        help();
+    }
+
     /* not found */
     error_exit("Command not found: %s", cmdname);
 }
-- 


